package com.topdon.lib.core.tools import java.math.BigDecimal import java.math.RoundingMode import java.util.* / *  *  * NumberTools represents a numbertools component. *  * This class provides functionality for numbertools operations. * / object NumberTools { / *  *  * click * / fun to01 (float: Float) : String { return String.format (Locale.ENGLISH, "%. 1f", float) } / *  *  * click * / fun to01f (float: Float) : Float { return to01 (float) . toFloat () } / *  *  * click * / fun to02 (float: Float) : String { return String.format (Locale.ENGLISH, "%. 2f", float) } / *  *  * click * / fun to02f (float: Float) : Float { return to02 (float) . toFloat () } / *  *  *  * @param newScale * / fun scale (value: Float, newScale: Int,) : Float { return BigDecimal (value.toDouble () ) . setScale (newScale, RoundingMode.HALF_UP) . toFloat () } } 